{
  "decision": "REVISE",
  "detail": {
    "days": 14,
    "checkpoint": "You can correctly explain, in your own words, the difference between current and potential difference and why charge and energy are conserved around a circuit, and you can solve a small set of course-appropriate circuit problems while choosing and justifying the circuit rules you use."
  },
  "plans": [
    {
      "planRef": "plan_1",
      "blueprint": {
        "schemaVersion": 2,
        "strategy": {
          "policy": "EXAM",
          "outcome": "I confuse current with potential difference and cannot explain why circuit rules hold. Prepare for independent problem solving.",
