          }
        ],
        "activities": [
          {
            "localId": "method_selection",
            "outcomeRefs": [],
            "scopeRefs": [
              "scope_1"
            ],
            "title": "Choose and defend the right circuit method on unfamiliar circuits",
            "activityType": "Method-selection practice with worked reasoning",
            "purpose": "Directly addresses the reported weakness by requiring an explicit method choice and justification before solving, on circuits the learner has not seen, using only methods their course has taught.",
            "instructions": "First, write down the circuit-analysis methods your course has actually taught so far (for example, if taught: equivalent resistance for series/parallel, voltage divider, current divider, Kirchhoff's laws, nodal analysis, mesh analysis, superposition, source transformation, Thevenin/Norton). Use only methods on that list. Then obtain or create three unfamiliar DC circuits that can be solved with those taught methods; you may take them from your course textbook exercises, past papers, or construct them yourself with given source values and resistor values. For each circuit: (1) sketch it and label all sources and resistors; (2) before solving, write one sentence naming the method you will use and one sentence justifying it from the circuit's topology and source arrangement (for example, 'I will use nodal analysis because there are two nodes and multiple parallel branches; it gives fewer equations than mesh analysis here'); (3) solve it fully, showing each step, and state the final voltages and currents with units; (4) check your answer by an independent route where possible (for example, verify KCL at a node, verify power balance, or re-solve a sub-part by a different taught method); (5) if your chosen method's assumptions or topology do not apply, say so and switch to a taught method that does. Do not use methods your course has not taught. If you cannot find suitable circuits, create them yourself with clear source and resistor values and state the expected answer you compute.",
            "completionCriterion": "For each of three unfamiliar circuits: a named taught method, a correct justification tied to the circuit's topology/source arrangement, a fully worked solution with correct final voltages and currents, and at least one independent check. At least two of the three choices must be the method that most directly fits the circuit, and all solutions must be correct.",
            "effort": {
              "lowMinutes": 60,
              "likelyMinutes": 90,
              "highMinutes": 120
            },
            "timeboxMinutes": 90,
            "commitment": {
              "category": "COMMITTED"
            },
            "hardDependencies": []
          }
        ],
        "decisions": {
          "assumptions": [
            "The learner has already been taught voltage and current concepts, as stated in the accepted outcome.",
            "The specific taught method repertoire is not supplied; the learner will list it from their course before choosing methods, and the task is restricted to that list."
          ],
          "tradeOffs": [
            "Only the first useful checkpoint is booked; the broader scope of method selection across all circuit types remains strategic and unbooked until this checkpoint is passed.",
            "No separate remediation activity is committed because the integrated task already embeds explanation, application and an independent changed example; extra work would need a distinct evidence contribution."
          ],
          "unresolvedUncertainty": [
            "The exact taught method repertoire is unknown, so the task cannot specify which methods are available; the learner must supply that list.",
            "No verified assessment weighting or deadline exists, so triage cannot prioritize by exam importance."
          ],
          "stoppingConditions": [
            "Stop when three unfamiliar circuits have been correctly solved with justified taught-method choices and independent checks.",
            "If a concrete failure appears (for example, a wrong method choice or a wrong solution), a bounded remediation activity may be added at that point."
          ]
        }
      }
    }
  ],
  "sharedDependencies": [],
  "tradeOffExplanation": "This plan commits only one integrated method-selection activity because the reported weakness is method choice, not concept knowledge, and there is no deadline or verified assessment weighting to justify broader coverage now. The full strategic scope of circuit method selection is preserved as INCLUDED but unbooked; further work is contingent on a concrete failure in this checkpoint. This sacrifices breadth for a clean, verifiable first checkpoint and avoids assuming a taught method repertoire that was not supplied."
}

