  },
  "plans": [
    {
      "planRef": "plan_1",
      "blueprint": {
        "schemaVersion": 2,
        "strategy": {
          "policy": "GENERAL",
          "outcome": "Complete and understand a short homework set of three linear equations with parentheses, eliminating sign errors when expanding negatives.",
          "explanation": "The learner has a bounded, authentic task: their own three-equation homework set. The reported weakness is sign errors when expanding negatives, so the work should address that rule directly inside the actual assignment rather than adding invented transfer exercises. No assignment text is supplied, so the learner must obtain and use the actual questions; invented fallback questions cannot satisfy the completion criterion. The work is short and resumable, fitting comfortably in a 30-minute timebox within the 60-minute daily ceiling. A single committed activity is sufficient; additional practice is optional unless a concrete sign error recurs.",
          "recommendedEffort": {
            "lowMinutes": 20,
            "likelyMinutes": 30,
            "highMinutes": 45
          },
          "phases": []
        },
        "scope": [
          {
            "scopeRef": "scope_1",
            "disposition": "INCLUDED",
            "contribution": "The negative-sign expansion rule is the reported weakness and must be applied and explained while solving the assigned equations."
          },
          {
            "scopeRef": "scope_2",
            "disposition": "INCLUDED",
            "contribution": "Solving linear equations is the actual homework task and the vehicle for checking sign handling."
          }
        ],
        "activities": [
          {
            "localId": "homework_set",
            "outcomeRefs": [],
            "scopeRefs": [
              "scope_1",
              "scope_2"
            ],
            "title": "Complete and check your three-equation homework set",
            "activityType": "Homework completion and error correction",
            "purpose": "Solve the actual assigned linear equations with parentheses, explicitly applying the negative-sign expansion rule, then check each answer and correct any sign errors.",
            "instructions": "Obtain the actual homework set of three linear equations with parentheses. For each equation, write the original problem, then expand parentheses carefully: when a negative sign precedes a parenthesis, change the sign of every term inside. Show each algebraic step clearly. Solve for the variable. Substitute your answer back into the original equation to check it. If a check fails, find and correct the actual sign or algebra error, then re-check. During the work, write one sentence for each equation explaining how you handled the negative sign. Do not invent replacement questions if the assignment is unavailable; use only the real assigned questions.",
            "completionCriterion": "All three assigned equations are solved, each solution is verified by substitution, any incorrect sign expansions are corrected, and you can explain in writing how the negative sign was handled in each equation.",
            "effort": {
              "lowMinutes": 20,
              "likelyMinutes": 30,
              "highMinutes": 45
            },
            "timeboxMinutes": 45,
            "commitment": {
              "category": "COMMITTED"
            },
            "hardDependencies": []
          },
          {
            "localId": "sign_practice",
            "outcomeRefs": [],
            "scopeRefs": [
              "scope_1"
            ],
            "title": "Optional extra practice: expanding negative parentheses",
            "activityType": "Targeted practice",
            "purpose": "Provide additional sign-expansion practice only if the homework reveals recurring errors.",
            "instructions": "If, after checking your homework, you find you made the same negative-sign expansion error in more than one equation, create three new expressions with a negative sign before parentheses, expand them, and verify each by substituting a simple number. Otherwise skip this activity.",
            "completionCriterion": "Three additional negative-parenthesis expansions are correctly performed and verified, or the activity is skipped because no recurring error occurred.",
            "effort": {
              "lowMinutes": 10,
              "likelyMinutes": 15,
              "highMinutes": 20
            },
            "timeboxMinutes": 20,
            "commitment": {
              "category": "OPTIONAL",
              "reason": "Additional practice is not required for the bounded homework goal; it is useful only if the committed homework reveals a recurring sign error."
            },
            "hardDependencies": [
              "homework_set"
            ]
          }
        ],
        "decisions": {
          "assumptions": [
            "The learner can access the actual assigned homework set of three linear equations with parentheses."
          ],
          "tradeOffs": [
            "No invented replacement questions are used because the completion criterion depends on the actual assignment; if the assignment is unavailable, the learner must obtain it before the task can be completed."
          ],
          "unresolvedUncertainty": [
            "The exact equations and whether the learner has already been taught the negative-sign expansion rule are not supplied."
          ],
          "stoppingConditions": [
            "Stop when all three assigned equations are solved, verified and any sign errors corrected with written explanations."
          ]
        }
      }
    }
  ],
  "sharedDependencies": [],
  "tradeOffExplanation": "The plan commits only to the actual homework set because the accepted outcome is bounded and authentic. Optional extra practice is left unscheduled and contingent on a recurring sign error, avoiding invented transfer exercises. If the assignment text is missing, the learner must obtain it rather than substitute fabricated questions."
}

